import { measureFramedWindow } from './src/logos-engine/v6-framed-window-observation.ts';
for (const size of [32,64,96,128]) {
  const rows=Array.from({length:size},()=>Array(size).fill(0));
  let small=0,large=0;
  for(let y=1;y+5<size-1;y+=8)for(let x=1;x+5<size-1;x+=8){
    const bigger=((x+y-2)/8)%2===1,side=bigger?6:4;
    if(bigger)large++;else small++;
    for(let dy=0;dy<side;dy++)for(let dx=0;dx<side;dx++)rows[y+dy][x+dx]=(dx===0||dy===0||dx===side-1||dy===side-1)?1:2;
    rows[y+1][x+1]=3;rows[y+1][x+2]=4;rows[y+2][x+1]=5;rows[y+2][x+2]=6;
  }
  const started=performance.now();const scene=measureFramedWindow(rows);const elapsedMs=performance.now()-started;
  console.log(JSON.stringify({domainPixels:size*size,smallFrames:small,largeFrames:large,compatiblePairs:small*large,scene,elapsedMs}));
}

